package net.civeira.phylax.feature.observe.observedslo.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.valueobject.ObjectiveVO;

@RequiredArgsConstructor
public class ObjectiveValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ObjectiveVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getObjective() {
    return value.map(ObjectiveVO::getObjective);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ObjectiveVO> getObjectiveValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param objective
   * @return
   */
  public T objective(ObjectiveVO objective) {
    this.value = Optional.of(objective);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param objective
   * @return
   */
  public T objective(Optional<ObjectiveVO> objective) {
    this.value = objective;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param objective
   * @return
   */
  public T objective(Integer objective) {
    this.value = Optional.of(ObjectiveVO.from(objective));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ObjectiveVO readObjective(final Optional<ObservedSlo> original,
      final ConstraintFailList fails) {
    ObjectiveVO result = value.orElse(original.map(ObservedSlo::getObjectiveValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "objective", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetObjective() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetObjectiveIfMatches(final String field) {
    if ("objective".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
